import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';

import { AIAssistViewComponent } from '@syncfusion/ej2-react-interactive-chat';
import { getAzureOpenAIAssist } from './ai-service';
import { marked } from 'marked';

import { useEffect } from 'react';
const SpeechToText = () => {
    let aiAssistViewObj = React.useRef(null);
    let azureApiKey = ''; // Your_Azure_OpenAI_API_Key
    let azureEndpoint = ''; // Your_Azure_OpenAI_Endpoint
    let azureDeployment = ''; // Your_Deployment_Name
    let azureApiVersion = ''; // Your_Azure_OpenAI_API_Version
    let stopStreaming = false;
    const toolbarSettings = {
        items: [{ iconCss: 'e-icons e-refresh', align: 'Right' }],
        itemClicked: (args) => toolbarItemClicked(args)
    };
    const footerToolbarSettings = {
        toolbarPosition: 'Bottom',
        items: [
            { iconCss: 'e-icons e-assist-send', align: 'Right' },
            { iconCss: 'e-icons e-assist-attachment-icon', align: 'Left', tooltip: 'Attach File' },
            { iconCss: 'e-icons e-assist-speech-to-text', align: 'Left' }
        ]
    };
    const enableAttachments = true;
    const attachmentSettings = {
        saveUrl: 'https://services.syncfusion.com/react/production/api/FileUploader/Save',
        removeUrl: 'https://services.syncfusion.com/react/production/api/FileUploader/Remove'
    };
    const speechToTextSettings = {
        enable: true
    };
    const bannerTemplate = () => {
        return (<div className="banner-info">
                <div className="e-icons e-listen-icon"></div>
                <h3>Speech To Text</h3>
                <i>Click the below mic-button to convert your voice to text.</i>
            </div>);
    };
    const streamResponse = async (response) => {
        let lastResponse = "";
        const responseUpdateRate = 10;
        let i = 0;
        const responseLength = response.length;
        while (i < responseLength && !stopStreaming) {
            lastResponse += response[i];
            i++;
            if (i % responseUpdateRate === 0 || i === responseLength) {
                const htmlResponse = marked.parse(lastResponse);
                aiAssistViewObj.current?.addPromptResponse(htmlResponse, i === responseLength);
                aiAssistViewObj.current?.scrollToBottom();
            }
            await new Promise(resolve => setTimeout(resolve, 15)); // Delay for streaming effect
        }
    };
    const onPromptRequest = async (args) => {
        stopStreaming = false;
        if (!aiAssistViewObj.current)
            return;
        try {
            const responseText = await getAzureOpenAIAssist({
                apiKey: azureApiKey,
                endpoint: azureEndpoint,
                deployment: azureDeployment,
                apiVersion: azureApiVersion,
                prompt: args.prompt || 'Hi',
            });
            await streamResponse(responseText);
        }
        catch (error) {
            aiAssistViewObj.current.addPromptResponse('⚠️ Something went wrong while connecting to the OpenAI service. Please check your API key or try again later.');
            stopStreaming = true;
        }
    };
    const toolbarItemClicked = (args) => {
        if (args.item.iconCss === 'e-icons e-refresh') {
            aiAssistViewObj.current.prompts = [];
        }
    };
    const stopRespondingClick = () => {
        stopStreaming = true;
    };
    return (<div className='control-pane'>
            <div className="control-section">
                <div className="integration-speech-to-text-assist-section">
                    <AIAssistViewComponent id="aiAssistView" ref={aiAssistViewObj} promptRequest={onPromptRequest} bannerTemplate={bannerTemplate} toolbarSettings={toolbarSettings} footerToolbarSettings={footerToolbarSettings} attachmentSettings={attachmentSettings} enableAttachments={enableAttachments} speechToTextSettings={speechToTextSettings} stopRespondingClick={stopRespondingClick}/>
                </div>
            </div>
        </div>);
};
export default SpeechToText;

const root = createRoot(document.getElementById('sample'));
root.render(<SpeechToText />);
